-- QLV-2026-Sprint-Pack-Build-Spec.md: the six final tasks, which table
-- has which, the lock before printing, and when each print pack was last
-- downloaded (to flag packs that changed since). List fields are JSON.
CREATE TABLE IF NOT EXISTS sprint_tasks (
  id TEXT PRIMARY KEY,          -- T1 to T6
  sort INTEGER NOT NULL,
  code TEXT NOT NULL,
  title TEXT NOT NULL,
  sector TEXT,
  situation TEXT,               -- list of paragraphs
  people TEXT,                  -- list of [role, number, what they do now, spare capacity]
  problem TEXT,
  work TEXT,                    -- list of [label, text]
  out_of_bounds TEXT,           -- list
  working TEXT,
  vulnerability TEXT,
  strong TEXT,                  -- list, judges only
  watch TEXT,                   -- list, judges only
  updated_at TEXT NOT NULL,
  updated_by TEXT
);
CREATE TABLE IF NOT EXISTS table_tasks (
  table_index INTEGER PRIMARY KEY,
  task_id TEXT NOT NULL,
  assigned_by TEXT NOT NULL,    -- auto or admin
  assigned_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS print_downloads (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,           -- table, all, spares, judge, mentor
  target TEXT NOT NULL,
  signature TEXT NOT NULL,
  downloaded_at TEXT NOT NULL,
  downloaded_by TEXT
);
CREATE INDEX IF NOT EXISTS print_downloads_target ON print_downloads(kind, target, id);

INSERT INTO sprint_tasks (id, sort, code, title, sector, situation, people, problem, work, out_of_bounds, working, vulnerability, strong, watch, updated_at, updated_by) VALUES ('T1', 1, 'Task 1', 'When every approval runs through one inbox', 'Marketing, communications and design', '["Brightline Studio is a branding and digital communications agency in Yaba, Lagos, with 12 staff and 15 retainer clients.", "Every final design approval, client revision request and print handoff goes through the Creative Director, Ms Funmi, on her personal WhatsApp and email. Nobody else has ever signed off work for a client.", "When she was away for 10 days in October, client reviews stalled, junior designers worked from outdated feedback and two wrong final files went to print. One reprint cost the agency ₦380,000."]', '[["Creative Director, Ms Funmi", "1", "Approves all final designs, takes every client revision request, decides which file goes to print", "2 hours a week"], ["Senior Designer", "1", "Leads large campaigns. Five years at the agency. Has never approved work for a client", "Half a day a week"], ["Account Managers", "2", "Client contact for briefs and billing. Cannot approve designs", "About 1 day a week each"], ["Designers", "5", "Produce artwork. Two joined this year", "None"], ["Copywriters", "2", "Write campaign copy", "None"], ["Office Manager", "1", "Invoices, admin, office supplies", "About 1 day a week"]]', 'Design how work moves from client brief to final file at Brightline without every routine decision passing through Ms Funmi.', '[["Budget", "₦500,000 over six months, for software, training and overtime allowances only."], ["Tools now", "Google Drive, Gmail, WhatsApp and Adobe Creative Cloud."], ["Decision rights", "Ms Funmi can delegate final approval to any staff member, in writing. Clients must be told in writing who approves their work."], ["Timing", "Ms Funmi is away again from 4 to 22 January."]]', '["Hiring a traffic manager, operations director or freelancers", "Limiting the revisions clients can ask for", "Pausing any client campaign while someone is away"]', 'While Ms Funmi is away in January, no wrong file goes to print and every client revision request gets a reply within two working days.', 'Quality control, approvals and file versions all live in one person''s inbox and memory.', '["Splits approval by type or value of work, so routine items no longer wait for the Creative Director", "Names one place where the current version of every file lives, and one rule for naming versions", "Puts revision requests in a shared queue that anyone on the account can see, with a named owner per client", "Uses the Senior Designer and Account Managers as approvers and backups within their spare capacity", "Tells clients in writing who approves their work, as the card requires"]', '["Plans that still route everything to Ms Funmi, just more politely", "Hiring freelancers or a traffic manager, which is out of bounds", "Buying software without saying who runs it"]', '2026-11-02T00:00:00Z', 'tasks.json') ON CONFLICT (id) DO NOTHING;
INSERT INTO sprint_tasks (id, sort, code, title, sector, situation, people, problem, work, out_of_bounds, working, vulnerability, strong, watch, updated_at, updated_by) VALUES ('T2', 2, 'Task 2', 'Field data that lives on laptops', 'Environment and development', '["GreenRoot Initiative is an environmental NGO in Abuja running three donor-funded projects across five states, with 16 staff.", "Field data and expense receipts are collected on paper or kept on personal laptops. Only the M&E Officer, Mr Danladi, knows how each donor''s report template maps to the data.", "Every quarter he spends two weeks chasing field officers on WhatsApp for missing receipts. The last two donor reports were late, and one donor has warned that the next payment could be held. Mr Danladi has been offered a job elsewhere and may leave by March."]', '[["Executive Director", "1", "Signs donor reports and manages donor relationships. Travels often", "None"], ["M&E Officer, Mr Danladi", "1", "Compiles every quarterly report and checks the data", "4 hours a week"], ["Finance Officer", "1", "Pays field expenses and matches receipts to budget lines", "About 1 day a week"], ["Project Leads", "3", "One per donor project. Supervise the field officers", "Half a day a week each"], ["Field Officers", "10", "Collect data in communities, keep receipts. Three days a week in areas with poor network", "None"]]', 'Design how GreenRoot collects field data and receipts and produces donor reports without depending on one person to chase, check and compile everything.', '[["Budget", "₦650,000 over six months, for data collection tools, cloud storage, data bundles and training only."], ["Tools now", "Google Sheets, Google Forms, Gmail and WhatsApp. Every field officer has an Android phone."], ["Decision rights", "The Executive Director can change any internal reporting rule. Donor report templates and deadlines cannot change."], ["Timing", "The next quarterly reports are due on 15 January."]]', '["Hiring consultants or new staff", "Reducing field locations or donor reporting requirements", "Giving cash advances without a logged record"]', 'The January reports go to donors by 15 January without anyone being chased on WhatsApp, and every expense in them has a matching receipt on file.', 'Records sit on personal devices and the reporting know-how sits in one person, who may be leaving.', '["Captures data and receipts at the source, on the phone, in a form that works offline and syncs later", "Writes down how each donor template maps to the data, so someone other than Mr Danladi can compile a report", "Gives Project Leads a weekly check of their own officers'' submissions, so gaps are found early, not in the last two weeks", "Names a backup compiler and has them run one report before Mr Danladi could leave"]', '["Plans that depend on good network in the field", "A new dashboard with nobody named to maintain it", "Cutting donor requirements, which is out of bounds"]', '2026-11-02T00:00:00Z', 'tasks.json') ON CONFLICT (id) DO NOTHING;
INSERT INTO sprint_tasks (id, sort, code, title, sector, situation, people, problem, work, out_of_bounds, working, vulnerability, strong, watch, updated_at, updated_by) VALUES ('T3', 3, 'Task 3', 'Everything is in Mrs Bisi''s cabinet', 'Administration and compliance', '["Okeke & Sons Packaging is a printing and packaging company in Ibadan with 18 staff.", "For 22 years the Admin Officer, Mrs Bisi, has kept every permit, levy receipt and agency contact in one filing cabinet and in her memory. She retires on 31 January.", "This year the company paid the same sanitation levy twice. The fire service closed the factory for a day because a certificate could not be found, even though it had been renewed."]', '[["Managing Director, Mr Okeke", "1", "Signs payments above ₦100,000. Meets officials only when called", "None"], ["Admin Officer, Mrs Bisi", "1", "Keeps all permits, receipts and agency contacts. Deals with every agency visit", "4 hours a week until she retires"], ["Accountant", "1", "Pays levies when the Admin Officer asks", "About 1 day a week"], ["Admin Assistant", "1", "Joined six months ago. Filing and reception", "About 2 days a week"], ["Factory Supervisor", "1", "Receives visitors at the gate", "Half a day a week"], ["Production staff", "13", "Run the machines", "None"]]', 'Design how Okeke & Sons keeps track of its permits, levies and agency visits so the company stays compliant after Mrs Bisi retires.', '[["Budget", "₦400,000 over six months, for scanning, digital storage, training and one review by a tax consultant only."], ["Tools now", "Google Drive, Google Calendar, Gmail, smartphones and a scanner-printer."], ["Decision rights", "The MD can authorise any staff member in writing to deal with agencies and approve levies up to ₦100,000."], ["Timing", "Mrs Bisi retires on 31 January."]]', '["Informal payments to officials", "A full-time legal or compliance retainer", "Hiring new staff"]', 'After Mrs Bisi retires, any permit or receipt can be shown to an inspector within 10 minutes of their arrival, and no levy is paid twice.', 'Compliance lives in one retiring person''s cabinet and memory.', '["Builds a single register of every permit and levy, with renewal dates, amounts, receipts and who to contact", "Uses calendar reminders well before each renewal, owned by a named person with a backup", "Writes a short gate procedure for agency visits that the Factory Supervisor can follow", "Uses Mrs Bisi''s remaining hours to walk the Admin Assistant through each agency, not just to scan files"]', '["Scanning everything without a register or naming rule", "Leaving the new process with one person, which recreates the problem", "Any informal settlement with officials, which is out of bounds"]', '2026-11-02T00:00:00Z', 'tasks.json') ON CONFLICT (id) DO NOTHING;
INSERT INTO sprint_tasks (id, sort, code, title, sector, situation, people, problem, work, out_of_bounds, working, vulnerability, strong, watch, updated_at, updated_by) VALUES ('T4', 4, 'Task 4', 'Training that walks out of the door', 'Customer service and people', '["Swiftline Bookings runs bus ticketing desks at two terminals in Port Harcourt.", "Four in ten desk agents leave every year. New agents learn by shadowing a colleague for four weeks, and booking errors such as wrong dates and refunds triple in a new agent''s first month.", "There are no written procedures. Fare rules change most months and are announced on WhatsApp. When anyone is unsure, they ask the Senior Desk Agent, Mrs Ibiere."]', '[["Operations Manager", "1", "Runs both terminals. Arranges all training", "3 hours a week"], ["Senior Desk Agent, Mrs Ibiere", "1", "Six years at Swiftline. Knows fare rules, refunds and group bookings", "4 hours a week"], ["Desk Agents", "8", "Sell tickets and handle changes. Four joined this year", "About 1 quiet hour per shift"], ["Terminal Bookers", "4", "Load passengers and check tickets", "None"], ["IT and Admin Officer", "1", "Looks after the booking software and staff accounts", "About 1 day a week"]]', 'Design how Swiftline trains new desk agents and keeps everyone up to date, so service no longer depends on who has been there longest.', '[["Budget", "₦450,000 over six months, for documentation tools, training materials and bonuses for staff who train others only."], ["Tools now", "The booking software (which cannot be changed), Google Docs, WhatsApp and a printed handbook from 2021."], ["Decision rights", "The Operations Manager can set training rules and pay bonuses within the budget."], ["Timing", "Three new desk agents start on 11 January."]]', '["Raising salaries above the market rate", "Hiring an HR manager", "Closing a desk for training"]', 'The three January starters handle bookings alone within one week, and their booking errors in the first month are no higher than experienced agents''.', 'Know-how walks out with every resignation, and everyone leans on one senior agent.', '["Turns the most common tasks and the costliest mistakes into short written steps, starting with refunds and date changes", "Gives fare rule changes one written home with a date, so WhatsApp is no longer the record", "Uses Mrs Ibiere''s hours to write and check procedures, and rewards others for keeping them current", "Has a simple first-week plan for new starters, with checks before they work alone"]', '["A huge manual nobody will read", "Training that still depends on shadowing Mrs Ibiere", "Closing a desk for training, which is out of bounds"]', '2026-11-02T00:00:00Z', 'tasks.json') ON CONFLICT (id) DO NOTHING;
INSERT INTO sprint_tasks (id, sort, code, title, sector, situation, people, problem, work, out_of_bounds, working, vulnerability, strong, watch, updated_at, updated_by) VALUES ('T5', 5, 'Task 5', 'The chambers that runs on one diary', 'Legal', '["Adeyemi & Co. is a litigation chambers in Abuja with 11 staff.", "The Head of Chambers, Barr. Adeyemi, allocates every brief himself. He keeps the master court diary in a leather diary and on his phone, and most client contacts are on his phone too.", "When he was at a conference abroad for 10 days in October, two adjourned dates were missed and one matter was struck out. A client could not get an update for a week, and associates were handed briefs outside their practice areas."]', '[["Head of Chambers, Barr. Adeyemi", "1", "Allocates all briefs, keeps the court diary, agrees fees with clients", "2 hours a week"], ["Senior Associates", "2", "Run the cases given to them and appear in court", "Half a day a week each"], ["Associates", "3", "Junior lawyers. Two were called to the Bar in the last two years", "None outside court"], ["Litigation Secretary", "1", "Types court processes and keeps case files", "About 1 day a week"], ["Clerk", "1", "Files at the court registry and collects hearing notices", "Half a day a week"], ["Accounts and Admin Officer", "1", "Billing, fee records and office admin", "About 1 day a week"], ["Interns", "2", "Law School students in chambers three days a week. Review cause lists", "Most of their time"]]', 'Design how Adeyemi & Co. allocates briefs, tracks court dates and keeps clients informed without depending on Barr. Adeyemi.', '[["Budget", "₦350,000 over six months, for software, training and overtime allowances only."], ["Tools now", "Gmail, WhatsApp, Microsoft Word and Google Calendar on the chambers'' account, which nobody uses yet."], ["Decision rights", "Barr. Adeyemi can delegate allocation of briefs to the Senior Associates in writing. Only he agrees fees with clients."], ["Timing", "He is away again from 11 to 22 January."]]', '["Hiring a practice manager or office administrator", "Passing briefs to other chambers", "Turning down new briefs"]', 'While Barr. Adeyemi is away in January, no court date is missed and every client gets an update on their matter at least every two weeks.', 'The court diary, client contacts and every allocation decision sit with one person.', '["Moves every court date into one shared diary that the Secretary, Clerk and lawyers can all see, with reminders and a named owner", "Sets simple rules for allocating briefs by practice area, which the Senior Associates apply", "Gives each matter a named lawyer responsible for client updates on a fixed rhythm", "Uses the Clerk and Interns to feed hearing dates from the registry and cause lists into the diary"]', '["Plans that ask Barr. Adeyemi to approve everything remotely", "Hiring a practice manager, which is out of bounds", "A shared diary with no one responsible for keeping it current"]', '2026-11-02T00:00:00Z', 'tasks.json') ON CONFLICT (id) DO NOTHING;
INSERT INTO sprint_tasks (id, sort, code, title, sector, situation, people, problem, work, out_of_bounds, working, vulnerability, strong, watch, updated_at, updated_by) VALUES ('T6', 6, 'Task 6', 'Only Mr Sunday knows the real stock', 'Retail and stock', '["Mama Nkechi Supermarkets has three branches in Ikeja, Lagos, with 22 staff.", "Every delivery and every transfer between branches goes through the Head Storekeeper, Mr Sunday. He records them in a paper logbook and arranges transfers on WhatsApp. He is the only person who knows the true stock position.", "Stock records and month-end counts differ by about 8% every month. When he took two weeks'' leave in September, transfers carried on over WhatsApp with nobody recording them, and the gap rose to 14%."]', '[["Owner, Mrs Nkechi", "1", "Approves purchases. Visits each branch weekly", "None"], ["Head Storekeeper, Mr Sunday", "1", "Receives deliveries, sends stock to branches, keeps the logbook", "3 hours a week"], ["Branch Supervisors", "3", "Run each branch and count the tills", "2 hours a week each"], ["Accounts Clerk", "1", "Records sales and supplier payments", "About 1 day a week"], ["Cashiers and shelf staff", "15", "Sell and restock", "None"], ["Driver", "1", "Moves stock between branches", "None"]]', 'Design how Mama Nkechi Supermarkets records, approves and checks stock movements so the stock position no longer lives with one person.', '[["Budget", "₦500,000 over six months, for software, barcode scanners and training only."], ["Tools now", "Google Sheets, Gmail, WhatsApp and point-of-sale tills that record sales but not stock."], ["Decision rights", "Mrs Nkechi can authorise any staff member in writing to approve transfers."], ["Timing", "The next full stock count is on 31 December."]]', '["Dismissing staff", "Closing any branch during trading hours", "Hiring a full-time inventory controller"]', 'At the 31 December count the gap between records and stock is below 3% in every branch, and every transfer has a signed record at both ends.', 'The true stock position lives in one person''s logbook and memory.', '["Requires every transfer to be recorded by the sender and confirmed by the receiver, not just arranged on WhatsApp", "Gives Branch Supervisors a regular spot count of high-value items, so gaps are found weekly, not monthly", "Names who approves transfers when Mr Sunday is away", "Keeps the record somewhere the Owner and Accounts Clerk can check without asking anyone"]', '["Assuming the cause is theft without evidence", "Buying scanners with no process for who scans and when", "Dismissing staff, which is out of bounds"]', '2026-11-02T00:00:00Z', 'tasks.json') ON CONFLICT (id) DO NOTHING;

-- The walkthrough link goes through the Worker so downloads are counted.
UPDATE settings SET value = json_set(value, '$.walkthrough_link', 'https://qlv2026.suturaworks.workers.dev/api/guide')
  WHERE key = 'lobby' AND json_extract(value, '$.walkthrough_link') IS NULL;

-- Thursday's guide post, and "Tomorrow is day one" moved from 9:00am to 12:00pm.
INSERT INTO lobby_posts (audience, body, send_at, created_at, updated_by)
  SELECT 'lobby', 'Your guide to Saturday is here 📘
See exactly how the sprint works, step by step, using a practice case: the task card, the A2 board, the plan, the critique and the response. Download it here: {walkthrough_link}', '2026-11-05T08:00:00Z', '2026-11-02T00:00:00Z', 'seed'
  WHERE NOT EXISTS (SELECT 1 FROM lobby_posts WHERE body LIKE 'Your guide to Saturday is here%');
UPDATE lobby_posts SET send_at = '2026-11-05T11:00:00Z' WHERE status = 'scheduled' AND send_at = '2026-11-05T08:00:00Z' AND body LIKE 'Tomorrow is day one%';
